package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.character.*;
import dev.tacticalcombat.uiapi.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.gui.widget.ClickableWidget;
import org.lwjgl.glfw.GLFW;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Actual widget events and constructed sheet/review controls, without claiming graphical acceptance. */
public final class CheckpointDPresentationTests {
    private static int count;
    private static void check(boolean value,String why){if(!value)throw new AssertionError(why);count++;}
    private static List<?> list(CharacterCanvas pane,String field)throws Exception {var f=CharacterCanvas.class.getDeclaredField(field);f.setAccessible(true);return (List<?>)f.get(pane);}
    private static Object value(Object record,String field)throws Exception {var m=record.getClass().getDeclaredMethod(field);m.setAccessible(true);return m.invoke(record);}
    private static Map<String,ClickableWidget> controls(CharacterCanvas pane)throws Exception {var out=new LinkedHashMap<String,ClickableWidget>();for(var row:list(pane,"controls"))out.put((String)value(row,"key"),(ClickableWidget)value(row,"widget"));return out;}
    public static void run()throws Exception {
        var entries=Srd2014Catalog.CLASSES.stream().map(c->new CreatorChoiceGrid.Entry(c.id(),c.name(),c.id())).toList();String[] choice={""};var grid=new CreatorChoiceGrid(new UiLayout.Rect(0,0,336,186),e->choice[0]=e.id(),84,62,40);
        for(int cycle=0;cycle<4;cycle++)for(int i=0;i<12;i++){grid.entries(entries,choice[0]);check(grid.mouseClicked(i%4*84+12,i/4*62+12,0),"Class click accepted");grid.entries(entries,choice[0]);check(grid.focusedIndex()==i,"Rebuild anchors keyboard focus to selected class, not Barbarian");for(int j=0;j<12;j++)check(grid.selectedIndex(j)==(j==i),"Exactly one gold selection after repeated changes");grid.setFocused(true);grid.keyPressed(i==11?GLFW.GLFW_KEY_LEFT:GLFW.GLFW_KEY_RIGHT,0,0);check(grid.selectedIndex(i),"Browsing focus leaves saved/preview selection unchanged");check(!grid.selectedIndex(grid.focusedIndex()),"Focused neighbor is not a second gold selection");}
        grid.entries(entries,"");for(int i=0;i<12;i++)check(!grid.selectedIndex(i),"Empty selection does not imply Barbarian");grid.setFocused(true);grid.focusedIndex(7);grid.keyPressed(GLFW.GLFW_KEY_ENTER,0,0);check(choice[0].equals("ranger"),"Keyboard confirmation chooses the focused entry");
        for(int[] size:List.of(new int[]{240,135},new int[]{320,180},new int[]{640,360},new int[]{854,480},new int[]{1280,720})){var outer=UiLayout.frame(size[0],size[1],980);var back=CreatorFooter.back(outer);check(back.fits(size[0],size[1]),"Back fits supported logical viewport");var child=WizardChildLayout.content(outer);check(child.x()!=outer.x(),"Child content moves but footer uses outer frame");for(int slot=0;slot<3;slot++){var r=CreatorFooter.action(outer,slot);check(r.fits(size[0],size[1])&&!r.overlaps(back),"Stable footer slot fits and clears Back");if(slot>0)check(!r.overlaps(CreatorFooter.action(outer,slot-1)),"Footer actions never overlap");}var inventory=InventoryWorkspace.geometry(outer);if(outer.width()-24>=380)check(inventory[1].y()==outer.y()+36,"Currency pane starts beside search, not below filters");}
        var dir=Files.createTempDirectory("checkpoint-d");var api=new UiApiService(new CharacterRepository(dir.resolve("campaigns.json")),new LibraryRepository(dir.resolve("library.json")),(op,a)->{throw new IllegalArgumentException("No runtime adapter");});var owner=new CharacterRepository.Principal(UUID.randomUUID(),false);var reply=api.handle(owner,UiApiService.Operation.LIBRARY_CREATE,args("profile","srd_5_1","mode","MANUAL","sheet",null));check(reply.code().equals("OK"),"Existing library contract creates fixture");var snapshot=reply.data();
        var review=new CharacterCanvas(new UiLayout.Rect(0,0,456,270));CharacterSheetUi.build(review,snapshot,true,null,null,null);var reviewControls=controls(review);check(reviewControls.keySet().stream().noneMatch(k->k.startsWith("health:")||k.startsWith("inspiration:")||k.startsWith("death")),"Review contains no HP, Inspiration or death-save editing widgets");var labels=new ArrayList<String>();for(var c:list(review,"captions")){var supplier=(java.util.function.Supplier<?>)value(c,"text");labels.add(supplier.get().toString());}check(labels.contains("Current HP / Max HP")&&labels.contains("Proficiency Bonus"),"Important sheet labels are spelled out");check(labels.contains("Successes")&&labels.contains("Failures"),"Death saves have two readable labeled rows");check(labels.stream().noneMatch(s->s.matches("(STR|DEX|CON|INT|WIS|CHA).* P$")),"Saving throws have no proficiency suffix");check(list(review,"panels").stream().anyMatch(p->{try{return value(p,"title").equals("Death Saves");}catch(Exception e){throw new RuntimeException(e);}}),"Death saves use a dedicated panel");check(CharacterSheetUi.layout(456).equipmentTop()<=270,"Compact core remains visible before equipment at 640x360 viewport");
        var sheet=new CharacterCanvas(new UiLayout.Rect(0,0,456,270));CharacterSheetUi.build(sheet,snapshot,true,new CharacterSheetUi.Actions(){public boolean healthEditable(){return true;}public boolean trackable(String section){return true;}public void health(String key,int delta){}public void track(RpgRecords.Change change){}public void inspect(FeatureReference.Entry e){}public void encounters(){}public boolean campaign(){return false;}},null,null);var widgets=controls(sheet);for(String key:List.of("health:hp:-","health:hp:+","health:temporary_hp:-","health:temporary_hp:+","inspiration:-1","inspiration:1")){var widget=widgets.get(key);check(widget!=null&&widget.getWidth()==18&&widget.getHeight()==18,"HP, Temp HP and Inspiration counters share compact dimensions");}check(!widgets.get("health:hp:+").active,"HP plus is disabled at max");check(!widgets.get("health:temporary_hp:-").active,"Temporary HP minus is disabled at zero");
        var state=new CreatorDraftState(snapshot);state.standardArray();var swap=AbilityWorkspace.class.getDeclaredMethod("adjust",CreatorDraftState.class,String.class,int.class,CenteredScoreField.class,boolean.class,Runnable.class);swap.setAccessible(true);for(int i=0;i<18;i++){String key=CreatorDraftState.ABILITIES.get(i%6),next=CreatorDraftState.ABILITIES.get((i+1)%6);String a=state.scores.get(key),b=state.scores.get(next);swap.invoke(null,state,key,1,null,false,(Runnable)()->{});check(state.scores.get(key).equals(b)&&state.scores.get(next).equals(a),"Array arrow swaps adjacent assignments");check(new HashSet<>(state.scoreValues().values()).equals(new HashSet<>(WizardModel.STANDARD_ARRAY)),"Array swaps always retain six unique presets");}
        check(AbilityWorkspace.help(WizardModel.ScoreMethod.STANDARD_ARRAY).contains("swap adjacent"),"Method help explains swap interaction");check(AbilityWorkspace.help(WizardModel.ScoreMethod.POINT_BUY).contains("27 points"),"Point-buy help explains budget");check(AbilityWorkspace.help(WizardModel.ScoreMethod.MANUAL).contains("1–30"),"Manual help states accepted bounds");for(var c:DashboardModel.checks(snapshot,true))check(c.display().matches("[+-][0-9]+"),"Detailed checks use totals without developer shorthand");
        System.out.println("Checkpoint D presentation checks passed: "+count);
    }
}
